#!/usr/bin/env python3
"""Generate the Deno report from retained, committed experiment evidence."""
from pathlib import Path
import json, statistics, html

R = Path(__file__).resolve().parents[1]
D = R / 'content/sites/deno/data'
def load(name): return json.loads((D/name).read_text())
def esc(value): return html.escape(str(value), quote=True)
def fmt(value, places=2): return f'{value:.{places}f}'
def pick(rows, model, case): return [r for r in rows if r['model']==model and r['case']==case]
def med(rows, key='whole_pipeline_s'): return statistics.median(r[key] for r in rows)
def component(rows, path):
    values=[]
    for row in rows:
        value=row['components']
        for key in path.split('.'): value=value[key]
        values.append(value)
    return statistics.median(values)
