browser=load('d8-browser-parity.json')
assert browser['states']==104 and browser['pixel_identical_states']==3 and browser['control_region_only_differences']==101 and not browser['outside_control_differences']
assert all(r['outside_observed_control_regions_pixel_identical'] for r in browser['records'])
