cases=[('warm-normal-publication','Unchanged cached publication'),('warm-forced-full','Forced full recomputation'),('application-cold','Fresh application state')]
expected={'deno':[1.31,13.16,11.16],'deno-agent':[.70,1.07,1.01]}
for model in expected:
    for (case,_),value in zip(cases,expected[model]):
        samples=pick(rows,model,case)
        assert len(samples)==5 and round(med(samples),2)==value
for case,value in [('warm-full',153.76),('application-cold',314.69),('prepared-input-warm-publication',25.57),('prepared-input-application-cold',159.58)]:
    samples=pick(native,'upstream',case)
    assert len(samples)==5 and round(med(samples),2)==value
for model,value in [('deno',134.86),('deno-agent',144.07)]:
    assert round(med(pick(initial,model,'warm-full')),2)==value
assert round(changed['whole_pipeline_s'],2)==135.08
assert round(load('d8-static-og-verification.json')['single_build_observation']['complete_s'],2)==23.35
for model,pair in [('deno',(16.51,16.70)),('deno-agent',(1.28,1.45))]:
    assert tuple(round(med(pick(old,model,case)),2) for case in ['warm-forced-full','application-cold'])==pair

def section(number, anchor, title, intro, body):
    return f'<section class="chapter" id="{anchor}" aria-labelledby="{anchor}-title"><p class="eyebrow">{number} / {anchor.replace("-"," ")}</p><h2 id="{anchor}-title">{title}</h2><p class="intro">{intro}</p>{body}</section>'
def link(url,label): return f'<a href="{esc(url)}">{esc(label)} ↗</a>'
def samples_cell(samples):
    values=[r['whole_pipeline_s'] for r in samples]
    return f'<td><strong>{fmt(med(samples))}s</strong><small>{fmt(min(values))}–{fmt(max(values))}s · 5 runs</small></td>'
def dual_table():
    s='<table class="dual"><caption>Migration publication · five serialized samples per model and mode · median and min–max range</caption><thead><tr><th scope="col">Mode</th><th scope="col">deno</th><th scope="col">deno-agent</th></tr></thead><tbody>'
    for case,label in cases:
        s+=f'<tr><th scope="row">{label}</th>'+''.join(samples_cell(pick(rows,m,case)) for m in ['deno','deno-agent'])+'</tr>'
    return s+'</tbody></table>'
def chart(title, caption, series, scale, unit='s'):
    s=f'<figure class="trace-chart"><figcaption><h3>{title}</h3><p>{caption}</p></figcaption><div class="axis" aria-hidden="true"><span>0</span><span>{scale/2:g}</span><span>{scale:g} {unit}</span></div>'
    for label,value,lo,hi,kind in series:
        places=1 if unit=='MiB' else 2
        s+=f'<div class="trace-row {kind}"><div class="trace-label"><span>{label}</span><strong>{fmt(value,places)} {unit}</strong></div><div class="rail" aria-hidden="true"><span class="bar" style="width:{value/scale*100:.4f}%"></span></div><p class="range">5 runs · {fmt(lo,places)}–{fmt(hi,places)} {unit}</p></div>'
    return s+'</figure>'
def series(samples, label, kind, memory=False):
    key=('maximum_measured_process_or_phase_rss_mib' if samples[0]['model']=='upstream' else 'maximum_measured_process_rss_mib') if memory else 'whole_pipeline_s'
    values=[r[key] for r in samples]
    return (label,statistics.median(values),min(values),max(values),kind)

parts=['''<header class="mast"><a class="brand" href="@path('/')"><i aria-hidden="true"></i>NIFT <span>LABS</span></a><nav aria-label="Report navigation"><a href="#parity">Parity</a><a href="#iteration">Edit loop</a><a href="#benchmarks">Build costs</a><a href="#maintenance">Maintenance</a><a href="#evidence">Evidence</a></nav><a class="back" href="@path('sites/')">All experiments ↗</a></header>
<main id="main" class="wrap">
<section class="hero" aria-labelledby="report-title"><div><p class="eyebrow">Experiment 05 / Deno Docs / October 2026</p><h1 id="report-title">Keep the source.<br><em>Shorten<br>the loop.</em></h1><p class="lede">A production documentation publication, reconstructed as two Nift projects. One keeps authoritative Markdown and structured references. The other maintains finished HTML.</p><p>Upstream is <a href="https://github.com/denoland/docs">denoland/docs</a>: Deno, Lume, Markdown/MDX, JSX, Prism and Tailwind. We pinned its source, preserved its production publication and compared two deliberately different maintenance contracts.</p><p class="independent">Independent Nift experiment. Not endorsed by Deno. Nift itself was not modified. This is a faithful migration, not an approximate redesign.</p></div><aside class="hero-art" aria-label="Pinned publication"><div class="orbit"><span class="node source">AUTHORITATIVE SOURCE</span><span class="node derive">DERIVE</span><span class="node compose">COMPOSE</span><span class="node publish">PUBLISH</span><strong>834</strong><span>HTML DOCUMENTS<br>ONE ACCEPTED PUBLICATION</span></div><div class="orb-foot"><span>UPSTREAM PIN</span><code>9e5dd8d930c8</code></div></aside></section>
<nav class="section-nav" aria-label="Reading order"><a href="#parity">01 / Prove the publication</a><a href="#architectures">02 / Choose the source</a><a href="#iteration">03 / Measure the loop</a><a href="#methodology">12 / Inspect the boundaries</a></nav>''']
parts.append(section('01','parity','The publication is the acceptance test.','Speed comes after the complete publication and behavior checks. Both migrations reproduce the frozen production reference.',
'''<div class="proof"><div><strong>2,573</strong><span>publication files</span></div><div><strong>834</strong><span>HTML documents</span></div><div><strong>481</strong><span>Markdown downloads</span></div><div><strong>834</strong><span>maintained OG images</span></div><div><strong>11,567</strong><span>local search records</span></div></div>
<div class="note"><strong>Fresh committed clones: every publication byte matches.</strong><p>Both final report-checkpoint clones began without application state, reproduced all 2,573 files by SHA-256 and left Git clean. Prepared dependencies and maintained inputs are explicitly outside that correctness observation.</p></div>
<div class="two"><div><h3>Routes, retrieval and retirement</h3><p>All 834 routes match status, MIME and HTML body hashes across the original and both models: 2,502 responses. Special HTTP checks cover redirects, Markdown content negotiation, health/404 behavior and cache headers.</p><p>Twenty production-default maintenance/lifecycle cases cover body edits, shared inputs, references and route add/rename/delete. <strong>Every changed publication equals forced recomputation</strong>, including ancillary output retirement.</p></div><div><h3>Browser parity, with differences retained</h3><p>The D8 recapture covers 104 model/theme/viewport states. Three screenshots exactly match corresponding D6 captures; 101 retain documented differences inside theme/search/copy-control regions. Every pixel outside those observed regions matches. The earlier D6 comparison also retains five tiny reference differences.</p><p>Twenty tab, copy, clipboard, search, mobile-navigation/TOC and tablet interactions pass separately. Bitmap dimensions and live CSS viewport/theme checks are recorded separately. <strong>This is not a claim that all screenshots are pixel-identical.</strong></p></div></div>
<p class="small">Search interaction fixtures exercise local two-hit, empty and error responses. They do not certify live Orama relevance/indexing. No upstream cloud upload, analytics or feedback was sent. Inherited duplicate IDs and potential unresolved links remain documented.</p>'''))
parts.append(section('02','architectures','Two sources. One publication.','The representations are intentionally different. The human path derives publication outputs; the agent-primary path maintains them.',
'''<div class="two"><article class="model"><p class="eyebrow">Nift deno / Authored-source / Human + agent</p><h3>Author the source. Derive the rest.</h3><ol class="pipeline"><li>Markdown/MDX, frontmatter + structured references <span class="state">AUTHORITATIVE</span></li><li>Corpus-bounded standalone renderer <span class="state derived">DERIVE</span></li><li>Transient verified HTML <span class="state cached">CACHE</span></li><li>Nift raw composition + explicit dependencies</li><li>Publication + search / LLM / download derivation</li></ol><p>Authored source organization, components and structured references remain editable. Generated HTML is disposable. Missing/corrupt cached outputs recover; source, renderer, metadata and toolchain changes invalidate verified derived work.</p></article><article class="model agent"><p class="eyebrow">Nift deno-agent / Rendered-source / Agent-primary</p><h3>Maintain the publication representations.</h3><ol class="pipeline"><li>HTML + explicit metadata/download/search/LLM projections <span class="state">AUTHORITATIVE</span></li><li>Nift raw composition + explicit dependencies</li><li>Publication</li></ol><p>No routine Markdown/MDX/JSX content renderer and no Deno runtime in normal publication. The smaller build trades derivation for coordinated source maintenance: the same edit may touch HTML, downloads, retrieval projections and metadata.</p></article></div>
<div class="note"><p>The renderer ports only behavior required by the pinned corpus; it does not reconstruct a general Lume framework. These are complete orchestrated pipelines, <strong>not native Nift <code>&#64;markup</code> performance measurements</strong>. OG images and compiled frontend assets are maintained publication inputs in both migrations.</p></div>'''))
changed_expected={'1-bodies':(4.48,1.72),'10-bodies':(4.91,2.29),'100-bodies':(5.61,1.71),'shared-layout':(2.03,1.75),'navigation':(15.55,1.80),'title-metadata':(17.75,1.66),'generated-reference-data':(14.88,1.56),'route-add':(16.80,1.69),'route-rename':(19.05,1.61),'route-delete':(19.69,1.93)}
