t='<table class="dual"><caption>Changed-input complete publication · one serialized observation per case/model, not five-run medians</caption><thead><tr><th scope="col">Changed input</th><th scope="col">deno</th><th scope="col">deno-agent</th></tr></thead><tbody>'
