ct='<table class="dual stage-table"><caption>Forced-full component medians · nested subsets and parallel counters are not additive</caption><thead><tr><th scope="col">Stage</th><th scope="col">deno</th><th scope="col">deno-agent</th></tr></thead><tbody>'
